import { randomUUID } from "node:crypto";
import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";

const dataFile = path.join(process.cwd(), "data", "books.json");

export async function getBooks() {
  const raw = await readFile(dataFile, "utf8");
  const books = JSON.parse(raw);
  return books.sort((a, b) => b.createdAt.localeCompare(a.createdAt));
}

export async function getBook(id) {
  const books = await getBooks();
  return books.find((book) => book.id === id) ?? null;
}

export async function addBook({ title, author, notes }) {
  const books = await getBooks();
  const book = {
    id: randomUUID(),
    title: title.trim(),
    author: author.trim(),
    notes: notes.trim(),
    status: "reading",
    createdAt: new Date().toISOString(),
    finishedAt: null,
  };
  books.push(book);
  await writeFile(dataFile, JSON.stringify(books, null, 2) + "\n");
  return book;
}

export async function finishBook(id) {
  const books = await getBooks();
  const book = books.find((item) => item.id === id);
  if (!book || book.status === "finished") return book ?? null;
  book.status = "finished";
  book.finishedAt = new Date().toISOString();
  await writeFile(dataFile, JSON.stringify(books, null, 2) + "\n");
  return book;
}

