  display: grid;
  gap: 0.6rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.book-row {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  align-items: center;
  padding: 0.85rem 1rem;
}

.book-row strong,
.book-row span {
  display: block;
}

.book-row span,
.empty {
  color: var(--muted);
}

.detail h1 {
  font-size: 2rem;
}

.notes {
  white-space: pre-wrap;
  line-height: 1.5;
}

.back {
  display: inline-block;
  margin-bottom: 1.2rem;
  color: var(--muted);
}

