import Link from "next/link";
import { createBook, markFinished } from "./actions";
import { getBooks } from "../lib/books";

export const dynamic = "force-dynamic";

function BookList({ books }) {
  if (books.length === 0) {
    return <p className="empty">Nothing here yet.</p>;
  }

  return (
    <ul className="book-list">
      {books.map((book) => (
        <li key={book.id} className="book-row">
          <Link href={`/books/${book.id}`}>
            <strong>{book.title}</strong>
            <span>{book.author}</span>
          </Link>
          {book.status === "reading" ? (
            <form action={markFinished}>
              <input type="hidden" name="id" value={book.id} />
              <button type="submit">Mark finished</button>
            </form>
          ) : null}
        </li>
      ))}
    </ul>
  );
}

export default async function HomePage({ searchParams }) {
  const books = await getBooks();
  const params = await searchParams;
  const reading = books.filter((book) => book.status === "reading");
  const finished = books.filter((book) => book.status === "finished");

  return (
    <main className="page">
      <header>
        <h1>Reading list</h1>
        <p>What you are reading, and what you have finished.</p>
      </header>

      <div className="stack">
        <section className="card">
          <h2>Add a book</h2>
          <form action={createBook}>
            <label>
              Title
              <input name="title" required />
            </label>
            <label>
              Author
              <input name="author" required />
            </label>
            <label>
              Notes
              <textarea name="notes" />
            </label>
            {params?.error === "missing" ? (
              <p className="muted">Title and author are required.</p>
            ) : null}
            <button type="submit">Add book</button>
          </form>
        </section>

        <section>
          <h2>Currently reading</h2>
          <BookList books={reading} />
        </section>

        <section>
          <h2>Finished</h2>
          <BookList books={finished} />
        </section>
      </div>
    </main>
  );
}

